import{_ as t}from"./chunks/academic-cross-substrate-authority-layers.1crA5U68.js";import{_ as n,C as s,o,c as r,E as i,a2 as p}from"./chunks/framework.BOeh4kYD.js";const v=JSON.parse('{"title":"Agent 不是权限边界：跨载体失效揭示了什么","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Agent 不是权限边界：跨载体失效揭示了什么","date":"2026-09-16","column":"digital-employee","category":"academic","article_type":"technical-analysis","edition":"research-center","research_question":"当文件、可见记忆和普通工作区证据看起来完全相同时，一个多 Agent 运行体还必须把哪些权限状态保存到真正产生外部效果的边界？","summary":"一项新的受控研究表明：即使两个世界向规划 Agent 暴露完全相同的工作区，若 actor-attempt 的授权状态存在于另一载体，安全的发布决策仍可能相反。最重要的结果不是‘模型看到权限就会正确推理’，而是执行时权限检查可以在不改变模型意图的情况下阻止固定的不安全动作。","sources":"arXiv:2609.08472; research/reading/A-20260916-01-cross-substrate-authority.md; research/analysis/A-20260916-01-cross-substrate-authority.md","cover":"/assets/covers/academic-cross-substrate-authority-boundary-cover-v2.webp"},"headers":[],"relativePath":"zh/digital-employee/2026-09-16-cross-substrate-authority-boundary.md","filePath":"zh/digital-employee/2026-09-16-cross-substrate-authority-boundary.md","lastUpdated":1789665186000}'),l={name:"zh/digital-employee/2026-09-16-cross-substrate-authority-boundary.md"};function c(d,a,h,u,g,b){const e=s("ArticleCover");return o(),r("div",null,[i(e,{image:"/assets/covers/academic-cross-substrate-authority-boundary-cover-v2.webp",kicker:"数字员工 · Academic Observation 008",title:"Agent 不是权限边界",summary:"模型可以看到文件，甚至可以看到权限说明。但真正决定下一次写入是否被授权的，应该是什么？",version:"DE008",status:"Academic Runtime V5 · 2026-09-16",languageHref:"/en/digital-employee/2026-09-16-cross-substrate-authority-boundary",languageLabel:"English"}),a[0]||(a[0]=p(`<h1 id="agent-不是权限边界-跨载体失效揭示了什么" tabindex="-1">Agent 不是权限边界：跨载体失效揭示了什么 <a class="header-anchor" href="#agent-不是权限边界-跨载体失效揭示了什么" aria-label="Permalink to &quot;Agent 不是权限边界：跨载体失效揭示了什么&quot;">​</a></h1><p>两次 Agent 执行，最后可以得到完全相同的文件。</p><p>它们可以呈现相同的 Git diff、相同的可见记忆、相同的候选制品。一个应该发布，另一个却必须阻断。</p><p>如果这听起来互相矛盾，真正缺失的事实根本不在文件里。</p><p>论文 <strong>Beyond Agent Harnesses: Cross-Substrate Authority for Multi-Agent Systems</strong> 于 2026 年 9 月 8 日首次提交 arXiv，研究的正是这种情况。它提出，多 Agent 系统会出现一种 <strong>cross-substrate authority gap（跨载体权限缺口）</strong>：规划 Agent 看见的是工作区和记忆状态，而真正决定某个下游效果是否允许发生的授权状态，却可能存在于另一个 Runtime、注册表或审批服务中。</p><p>这个区别很容易被忽略，因为现代 Agent 系统很擅长把一切都变成“上下文”。策略可以写进 system prompt，审批结果可以摘要进记忆，共享文件也可以写着“是谁修改的”。但这些表示都不必然证明：</p><p><strong>此刻这个 actor，在这一次 execution attempt 中，仍被授权针对这些字节、这个 consumer scope，产生这个具体效果。</strong></p><p>因此，真正的权限边界可能并不在模型会话本身。</p><h2 id="字节完全一样-正确动作却可以相反" tabindex="-1">字节完全一样，正确动作却可以相反 <a class="header-anchor" href="#字节完全一样-正确动作却可以相反" aria-label="Permalink to &quot;字节完全一样，正确动作却可以相反&quot;">​</a></h2><p>论文构造了一个刻意令人不舒服的场景。</p><p>两个 coding agents 修改同一个共享策略文件及其消费者。在两个世界里，下游 Agent 看到的最终文件逐字节相同，未提交的 Git 证据相同，可见记忆也相同。</p><p>在 <strong>aligned world</strong> 中，每个写入者都对自己的 scope 拥有授权，因此可以发布。</p><p>在 <strong>crossed world</strong> 中，两个写入者被交换到了错误的 scope。最终字节碰巧仍然一样，但制品必须停止发布并进入协调。</p><p>规划器看到的观察完全相同，正确动作却改变了。</p><p>作者把它形式化为 observation aliasing：如果世界 <code>x</code> 和 <code>y</code> 暴露相同观察 <code>O</code>，但一个要求 <code>publish</code>、另一个要求 <code>block</code>，那么只看到 <code>O</code> 的确定性策略必然在两个世界输出同一个动作，因此至少有一个世界会错。永远阻断可以避免不安全发布，却会在真正已授权的世界制造不必要阻断。</p><p>这首先不是“模型不够聪明”。</p><p>它是一个<strong>信息边界问题</strong>。</p><p>如果区分两个世界的关键事实根本不在观察里，再强的推理也无法从同一份观察中凭空恢复这个缺失事实。</p><h2 id="权限不是-这个-agent-有权限-这么简单" tabindex="-1">权限不是“这个 Agent 有权限”这么简单 <a class="header-anchor" href="#权限不是-这个-agent-有权限-这么简单" aria-label="Permalink to &quot;权限不是“这个 Agent 有权限”这么简单&quot;">​</a></h2><p>常见表达是：这个 Agent 有没有权限？</p><p>这往往太粗。</p><p>论文使用的 decision relation 把多项事实绑在一起：actor 与 attempt 身份、session 与 consumer scope、输入和制品哈希、被授权的动作范围、attempt 的终态、下游使用授权，以及 evidence generation。</p><p>重点在于“关系”。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不是：</span></span>
<span class="line"><span>    agent_A = authorized</span></span>
<span class="line"><span></span></span>
<span class="line"><span>而更接近：</span></span>
<span class="line"><span>    actor A</span></span>
<span class="line"><span>    + attempt 17</span></span>
<span class="line"><span>    + artifact hash H</span></span>
<span class="line"><span>    + consumer scope S</span></span>
<span class="line"><span>    + action &quot;publish&quot;</span></span>
<span class="line"><span>    + terminal state</span></span>
<span class="line"><span>    + downstream authorization</span></span>
<span class="line"><span>    + evidence generation G</span></span>
<span class="line"><span>    = admissible relation</span></span></code></pre></div><p>同一个 Agent 可能对一个 scope 有权，对另一个 scope 无权。同一份字节，在一种执行谱系下可以发布，在另一种谱系下必须阻断。先前有效的审批，也可能在工作区变化或授权 generation 更新以后变成陈旧证据。</p><p>所以，“这个 Agent 当时有权限”并不是一条足够强的审计事实，除非这个权限真正绑定到了后来发生的那次动作。</p><h2 id="论文实际上拆开了三个问题" tabindex="-1">论文实际上拆开了三个问题 <a class="header-anchor" href="#论文实际上拆开了三个问题" aria-label="Permalink to &quot;论文实际上拆开了三个问题&quot;">​</a></h2><p>这篇论文一个很重要的价值，是没有把“让模型看到权限”和“真正执行权限”当成同一种机制。</p><p>三个实验形成了一条很清楚的链。</p><h3 id="实验一-先把缺失的权限事实补进来" tabindex="-1">实验一：先把缺失的权限事实补进来 <a class="header-anchor" href="#实验一-先把缺失的权限事实补进来" aria-label="Permalink to &quot;实验一：先把缺失的权限事实补进来&quot;">​</a></h3><p>实验一交叉组合四个 held-out semantic templates、两个模型路由、两个 lineage directions、两种外部发布状态和四种 evidence arms，共形成 32 个 matched strata、128 个目标执行。</p><p>作者报告：</p><ul><li>Git-only control <code>G0</code>：最终语义成功 <strong>0/32</strong></li><li>有候选制品但缺权限事实的 <code>C0</code>：<strong>0/32</strong></li><li>加入 canonical raw authority receipts 的 <code>R0</code>：<strong>32/32</strong></li><li>把同一组 admitted primitives 包装成 typed relation 的 <code>W0</code>：<strong>32/32</strong></li></ul><p>这些数字都是论文作者报告的结果；本次 Academic 运行没有独立复现实验。</p><p>这里最值得保留的解释不是“typed governance 已经解决问题”。真正有识别力的是 <code>R0</code> 与 <code>C0</code> 的对照：补上缺失的外部权限事实以后，论文构造的歧义被解除。至于 typed <code>W0</code>，在这个实验中并没有显示出比等量 raw authority information 更高的最终语义正确率。</p><p>先重要的是信息本身，然后才是包装形式。</p><h3 id="实验二-模型看到了-规划仍然不可靠" tabindex="-1">实验二：模型看到了，规划仍然不可靠 <a class="header-anchor" href="#实验二-模型看到了-规划仍然不可靠" aria-label="Permalink to &quot;实验二：模型看到了，规划仍然不可靠&quot;">​</a></h3><p>实验二进一步问：面对 observation-equivalent 的共享工作区，规划 Agent 能不能安全决定是否发布？</p><p>论文一共执行 <strong>96 次 planning calls</strong>，报告普通工作区证据、raw receipts 和 typed relation 三个条件下的 first-action correctness 分别为 <strong>14/32、19/32、15/32</strong>。</p><p>在 crossed worlds 中，不安全发布分别为 <strong>12/16、9/16、6/16</strong>。</p><p>但最后这个 6/16 不能简单理解成“大幅变安全”，因为 typed relation 条件同时出现了 <strong>11/32 个 invalid or absent outputs</strong>。模型拆分结果更说明问题：一个路由看起来几乎不做不安全发布，却有很多行根本没有形成有效意图；另一个路由能正常解析 relation，却仍会在多个 crossed cases 中提出不安全发布。</p><p>因此，一个总的“安全分”会掩盖问题。</p><p>规划器可能因为真正理解规则而保守，也可能因为根本没有正常行动而显得保守。安全效果率、正确动作率、不必要阻断率、缺失意图率，是不同的指标。</p><h3 id="实验三-把模型意图固定住" tabindex="-1">实验三：把模型意图固定住 <a class="header-anchor" href="#实验三-把模型意图固定住" aria-label="Permalink to &quot;实验三：把模型意图固定住&quot;">​</a></h3><p>第三个实验对系统架构最有启发。</p><p>研究者直接拿实验二 typed-relation 条件下<strong>已经生成的 32 个 first-action intents</strong>重放，<strong>不再调用模型</strong>。模型没有第二次思考机会，唯一变化是执行时 validator。</p><p>论文报告，这 32 个固定意图中包含 6 个 crossed-world 的不安全发布请求。加入 execution guard 后，这 6 个全部变成 safe non-effects；与此同时，<strong>12/12 个有效且已授权的 publish intents</strong>全部被允许，在这个 valid-intent 集合中出现 <strong>0/12</strong> 的误拒绝。</p><p>模型的意图没有变，最终效果变了。</p><p>这就是最关键的区别。</p><h2 id="让模型看到权限-与真正拥有效果权限-是两层" tabindex="-1">让模型看到权限，与真正拥有效果权限，是两层 <a class="header-anchor" href="#让模型看到权限-与真正拥有效果权限-是两层" aria-label="Permalink to &quot;让模型看到权限，与真正拥有效果权限，是两层&quot;">​</a></h2><p>Prompt 可以明确写：</p><blockquote><p>只有当前 actor 对制品 scope 有权限时才能发布。</p></blockquote><p>模型可以读懂这条规则，甚至可以一字不差地复述。</p><p>但 prompt 仍然属于规划器的观察。它本身并不能保证最终效果边界一定执行这条规则。</p><p>论文的实验支持一种两层结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规划阶段：</span></span>
<span class="line"><span>    暴露权限证据</span></span>
<span class="line"><span>    让模型理解、推理、解释</span></span>
<span class="line"><span></span></span>
<span class="line"><span>执行阶段：</span></span>
<span class="line"><span>    校验 actor / attempt / artifact / scope 关系</span></span>
<span class="line"><span>    重新检查策略相关字节</span></span>
<span class="line"><span>    决定 mutation 是否真正发生</span></span></code></pre></div><p>第一层提高判断质量。</p><p>第二层决定提议是否变成效果。</p><p>这并不是反对 Agent 智能，而是给 Agent 智能划出一个它不需要冒充的边界。</p><h2 id="research-center-综合-四种载体-最后才跨过一个效果边界" tabindex="-1">Research Center 综合：四种载体，最后才跨过一个效果边界 <a class="header-anchor" href="#research-center-综合-四种载体-最后才跨过一个效果边界" aria-label="Permalink to &quot;Research Center 综合：四种载体，最后才跨过一个效果边界&quot;">​</a></h2><p>下面这张图是 <strong>Research Center 综合模型</strong>，不是论文图的复刻，也不是论文作者声称已经标准化的架构。</p><p><img src="`+t+`" alt="规划上下文、工作区字节、持久 attempt/provenance、authority state 与 mutation boundary 的概念综合图。"></p><p>一个生产系统可以把状态至少拆成四种载体。</p><h3 id="_1-planner-visible-context" tabindex="-1">1. Planner-visible context <a class="header-anchor" href="#_1-planner-visible-context" aria-label="Permalink to &quot;1. Planner-visible context&quot;">​</a></h3><p>这是模型可以直接推理的世界：任务指令、记忆、检索事实、策略文本、工具返回，也可以包括权限回执。</p><p>它负责支持判断。</p><h3 id="_2-workspace-artifact-bytes" tabindex="-1">2. Workspace / artifact bytes <a class="header-anchor" href="#_2-workspace-artifact-bytes" aria-label="Permalink to &quot;2. Workspace / artifact bytes&quot;">​</a></h3><p>它回答另一个问题：当前究竟有哪些材料？</p><p>内容哈希可以证明“当时看到的是哪些字节”，却不必然证明“谁被授权生产或发布这些字节”。</p><h3 id="_3-durable-attempt-provenance-state" tabindex="-1">3. Durable attempt / provenance state <a class="header-anchor" href="#_3-durable-attempt-provenance-state" aria-label="Permalink to &quot;3. Durable attempt / provenance state&quot;">​</a></h3><p>它把材料绑定到一次具体执行：哪一次 attempt 运行过、是否已经终态、使用了什么输入、生成了什么 artifact。</p><p>如果缺少这一层，共享工作区很容易抹掉“这些材料到底是哪次执行产生的”这条关系。</p><h3 id="_4-authority-state" tabindex="-1">4. Authority state <a class="header-anchor" href="#_4-authority-state" aria-label="Permalink to &quot;4. Authority state&quot;">​</a></h3><p>它回答：当前这个 actor-attempt-artifact-scope 关系，是否仍然被允许跨入下游效果？</p><p>真正的 mutation boundary 应消费这条可验证关系，而不是从聊天摘要里猜测它。</p><p>因此可以得到一个简单原则：</p><blockquote><p><strong>权限证据可以提前进入模型上下文，但权限本身必须一直活到动作真正产生效果的那一刻。</strong></p></blockquote><h2 id="git-可以足够——前提是-git-真的承载完整权限关系" tabindex="-1">Git 可以足够——前提是 Git 真的承载完整权限关系 <a class="header-anchor" href="#git-可以足够——前提是-git-真的承载完整权限关系" aria-label="Permalink to &quot;Git 可以足够——前提是 Git 真的承载完整权限关系&quot;">​</a></h2><p>这篇论文不应该被概括成“Git 不够”。</p><p>作者明确保留了一个重要的 negative control：如果经过认证的 commit 已经绑定了 actor、attempt、scope、artifact，而且这些 Git 元数据本身就是下游使用的权威依据，那么 Git 可以承担权限边界。</p><p>只有当某些必需事实仍然存在于 Git/工作区之外时，才出现 cross-substrate governance 的必要性，例如：外部审批服务、任务 Runtime、撤销注册表、可变化的 evidence generation，或者尚未提交的共享工作区 provenance。</p><p>所以更好的问题不是：</p><blockquote><p>Git 还是 Agentic OS？</p></blockquote><p>而是：</p><blockquote><p><strong>权威关系究竟存在在哪里？下游效果能不能不靠猜测就验证它？</strong></p></blockquote><p>这个问题更有普遍性。</p><h2 id="工作完成-与-允许下游使用-不是一回事" tabindex="-1">“工作完成”与“允许下游使用”不是一回事 <a class="header-anchor" href="#工作完成-与-允许下游使用-不是一回事" aria-label="Permalink to &quot;“工作完成”与“允许下游使用”不是一回事&quot;">​</a></h2><p>论文 decision relation 里还有一个很值得注意的分离：attempt terminal state 与 downstream-use authorization 是两项不同事实。</p><p>一个 Agent 可以成功完成任务，但输出尚未被允许公开发布。</p><p>一个 artifact 可以已经通过审核，但工作区随后发生变化，使原来的批准失效。</p><p>同一份可发布内容，也可能因为执行发布动作的 actor 改变而必须重新判断权限。</p><p>如果把这些状态都压成一个 <code>done=true</code>，正好会制造论文希望揭示的那类歧义。</p><p>对于持久化 Agent 工作，至少应该分别回答：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工作完成了吗？</span></span>
<span class="line"><span>哪一次 attempt 产生了这些字节？</span></span>
<span class="line"><span>现在还是同一份字节吗？</span></span>
<span class="line"><span>下游使用得到批准了吗？</span></span>
<span class="line"><span>批准的是哪个 actor 和 scope？</span></span>
<span class="line"><span>这个批准现在仍有效吗？</span></span></code></pre></div><p>生命周期状态只能回答其中一部分。</p><h2 id="这不是一个完整的安全模型" tabindex="-1">这不是一个完整的安全模型 <a class="header-anchor" href="#这不是一个完整的安全模型" aria-label="Permalink to &quot;这不是一个完整的安全模型&quot;">​</a></h2><p>证据边界必须保持清楚。</p><p>论文是在两个四模板 family、两个模型 route 上做的受控 mini-benchmark。实验三只是重放 32 个先前已经生成的 intents。作者自己明确指出，真实部署中的发生频率需要另一套采样设计。</p><p>研究还假设 host 非恶意、actor credential 真实、authority database 未被攻破、哈希抗碰撞。</p><p>它没有解决：</p><ul><li>恶意 host；</li><li>actor credential 被盗；</li><li>大规模密码学身份；</li><li>多租户策略组合；</li><li>语义业务裁决；</li><li>所有并发和恢复故障。</li></ul><p>因此最稳妥的结论是一个机制结论：</p><p><strong>当权限状态对决策关键、但存在于 planner-visible substrate 之外时，让模型看到权限事实有助于解除信息歧义；而若希望下游效果可靠，仍然需要一个独立可验证的执行边界。</strong></p><p>这个结论已经足够重要，不需要被扩大成“完整安全方案”。</p><h2 id="安全性与可用性应该分别计量" tabindex="-1">安全性与可用性应该分别计量 <a class="header-anchor" href="#安全性与可用性应该分别计量" aria-label="Permalink to &quot;安全性与可用性应该分别计量&quot;">​</a></h2><p>规划实验还有一个很实际的测量启示。</p><p>一个拒绝所有动作的系统可以做到零不安全发布，但它没有生产价值。</p><p>一个在困难场景里经常生成不了有效动作的模型，也可能在某个分母上看起来“更安全”，同时可用性已经很差。</p><p>因此生产监控至少应拆开：</p><ul><li>unsafe effects；</li><li>已授权有效效果的放行率；</li><li>unnecessary blocks；</li><li>invalid / missing intents；</li><li>stale-evidence denials；</li><li>recovery-required cases。</li></ul><p>这比一个总的“Agent 安全分”健康得多。</p><p>也只有这样，规划质量与执行门禁才能被独立改进。</p><h2 id="给数字员工系统的一条实用规则" tabindex="-1">给数字员工系统的一条实用规则 <a class="header-anchor" href="#给数字员工系统的一条实用规则" aria-label="Permalink to &quot;给数字员工系统的一条实用规则&quot;">​</a></h2><p>不采用任何特定“Agent OS”概念，也可以提炼出一条很直接的规则：</p><p><strong>不要把 Agent 会话本身当作“效果已经被授权”的证明。</strong></p><p>模型当然应该读取证据、提出动作、解释为什么它认为一次发布、数据库写入、handoff 或外部调用是合理的。</p><p>但在真正跨过 consequential mutation 之前，系统还要回答一个更精确的问题：</p><blockquote><p>当前经过验证的关系，是否仍然授权<strong>这个 actor、这次 attempt、这份 artifact、这个 action、这个 consumer scope，以及这个 evidence version</strong>？</p></blockquote><p>如果这个问题无法被证明，系统应该把不确定性保留成 Blocked 或 reconciliation，而不是从上下文中“生成”出权限。</p><p>这不是不信任模型。</p><p>而是承认：<strong>推理与授权，本来就是两份工作。</strong></p><h2 id="还有哪些问题没有解决" tabindex="-1">还有哪些问题没有解决 <a class="header-anchor" href="#还有哪些问题没有解决" aria-label="Permalink to &quot;还有哪些问题没有解决&quot;">​</a></h2><p>下一步的问题并不小。</p><p>跨组织的 authority relation 应该怎样表示？Artifact 已经 handoff 以后，撤销如何传播？什么条件下 signed Git commit 可以替代外部 registry？哪些谓词适合确定性检查，哪些仍然需要人或模型裁决？Runtime 恢复以后，怎样证明上一次外部效果究竟发生了没有？Authority store 自己又如何被审计和复制？</p><p>这些问题超出了当前论文的固定实验。</p><p>但这项研究至少让一种常见设计更难再被忽略：</p><p><strong>一个上下文完整、逻辑自洽的模型会话，并不自动等于最终权限边界。</strong></p><p>Agent 可以知道。</p><p>工作区可以一致。</p><p>计划可以合理。</p><p>最后那个效果，仍然可能没有被授权。</p><h2 id="来源与证据边界" tabindex="-1">来源与证据边界 <a class="header-anchor" href="#来源与证据边界" aria-label="Permalink to &quot;来源与证据边界&quot;">​</a></h2><ol><li>Yang Li, Sergey Volkov, Hai Liu, Zongsi Xu, Xiyu Chen, Tuo Zhou, Dian Shao, Hao Sun, Ye Lu，<strong>Beyond Agent Harnesses: Cross-Substrate Authority for Multi-Agent Systems</strong>，arXiv:2609.08472，首次提交于 2026-09-08 — <a href="https://arxiv.org/abs/2609.08472" target="_blank" rel="noreferrer">https://arxiv.org/abs/2609.08472</a></li><li>论文 HTML 全文 — <a href="https://arxiv.org/html/2609.08472" target="_blank" rel="noreferrer">https://arxiv.org/html/2609.08472</a></li><li>Brian Jin，<strong>Fresh Context Is Not Enough: An Agent Action Needs a Valid Chain Back to Its Decision</strong>，DEV Community，2026-09-11 — <a href="https://dev.to/kikashy/fresh-context-is-not-enough-an-agent-action-needs-a-valid-chain-back-to-its-decision-1afk" target="_blank" rel="noreferrer">https://dev.to/kikashy/fresh-context-is-not-enough-an-agent-action-needs-a-valid-chain-back-to-its-decision-1afk</a></li><li>受治理 Deep Reading — <code>research/reading/A-20260916-01-cross-substrate-authority.md</code></li><li>受治理 Research Analysis — <code>research/analysis/A-20260916-01-cross-substrate-authority.md</code></li></ol><p>**证据边界：**本次 Academic 对象以 arXiv 论文为一手证据。全部实验数字均按论文作者报告处理，本次运行未做独立复现。四载体模型以及“权限是一条必须持续到 mutation boundary 的关系”属于 Research Center 综合；DEV Community 文章属于二手语境材料，不是独立实验复现。</p>`,134))])}const f=n(l,[["render",c]]);export{v as __pageData,f as default};
